do $$ begin if to_regclass('public.fin_policies') is not null or to_regclass('public.fin_policy_versions') is not null or to_regclass('public.fin_approval_stages') is not null or to_regclass('public.fin_policy_exceptions') is not null or to_regclass('public.fin_approval_delegations') is not null or to_regprocedure('public.fin_request_policy_approval(uuid,uuid,jsonb,text,text,jsonb)') is not null or to_regprocedure('public.fin_act_on_approval_v2(uuid,text,text,text)') is not null or to_regprocedure('public.fin_policy_evaluate(uuid,uuid,jsonb)') is not null or exists (select 1 from information_schema.columns where table_schema='public' and table_name='fin_approval_requests' and column_name='policy_snapshot') or to_regprocedure('public.fin_request_approval(uuid,uuid,uuid[],text)') is null or (select value from public.fin_settings where key='schema_version') <> 'financial-graph-1' then raise exception 'Policy Engine rollback incomplete'; end if; end $$;
